        var mockLogger = new Mock<ILogger>();
        var mockGarnetClient = new Mock<GarnetClientSession>();
        var aofSyncTaskInfo = new AofSyncTaskInfo(
            null,
            null,
            "localNodeId",
            "remoteNodeId",
            mockGarnetClient.Object,
            0,
            mockLogger.Object);

        // Act
        await aofSyncTaskInfo.ReplicaSyncTaskAsync();

        // Assert
